      LOB = {c:'#3e4a53', glow:'#ffe2b8', gk:0.7}, CAP = {c:'#d1d4d3', m:0, lk:0.3}, ROOF = '#8e9395', GREEN = '#6f8c5a', TREE = '#557548',
      WALL = {c:'#e3e0d8', m:1, fh:3.8, cw:2.6}, WALL2 = {c:'#c9c4b8', m:1, fh:3.8, cw:2.6}, DECK = '#bdb7aa', HELI = '#5a5f63', POD = {c:'#86959c', m:1, fh:4.5, cw:4.0};
