    const tower = (R, h, notch, belts, roofTop) => {
      const [x0, z0, x1, z1] = bbP(R), n = notch;
      const P = [[x0 + n, z0], [x1 - n, z0], [x1 - n, z0 + n], [x1, z0 + n], [x1, z1 - n], [x1 - n, z1 - n], [x1 - n, z1], [x0 + n, z1], [x0 + n, z1 - n], [x0, z1 - n], [x0, z0 + n], [x0 + n, z0 + n]];
      prism(B.p(CAP), offP(P, -1.2), -7, 0.3);                 // granite plinth down the slope (the base is the highest ground in r)
      prism(B.p(LOB), offP(P, 1.5), 0.3, 14, false); prism(B.p(CAP), offP(P, -0.3), 14, 15.2);
      prism(B.p(GL), P, 15.2, h - 4, false);
      finsP(B.p(MUL), P, 15.2, h - 4, 3.0, 0.42, 0.16, 0.6);
      bandsP(B.p(CAP), P, 15.2, h - 4, 4.6, 0.3, 0.1);
      for (const y of belts) prism(B.p(LOUV), offP(P, -0.35), y, y + 8.6, false);
      prism(B.p(CAP), offP(P, -0.3), h - 4, h); flat(B.p(ROOF), offP(P, 0.4), roofTop);
      return {x0, z0, x1, z1, cx:(x0 + x1)/2, cz:(z0 + z1)/2};
    };
    const t1 = tower(U.T1, 388.1, 3.0, [80, 158, 236, 306], 384.5), t2 = tower(U.T2, 299.3, 3.0, [92, 186], 296);
    // T1 roof: the roof garden and the helipad
