    function fw(f){ return f*(t1.x1 - t1.x0); }
    const hp = []; for (let k = 0; k < 24; k++){ const a = k/24*TAU; hp.push([t1.cx + 6 + Math.cos(a)*11, t1.cz - 4 + Math.sin(a)*11]); }
