    prism(B.p(CAP), [[bx0, bz0], [bx1, bz0], [bx1, bz1], [bx0, bz1]], -7, 0.3); prism(B.p(LOB), [[bx0 + 8, bz0 + 8], [bx1 - 8, bz0 + 8], [bx1 - 8, bz1 - 8], [bx0 + 8, bz1 - 8]], 0.3, 12.5, false);
    for (let x = bx0 + 3; x <= bx1 - 3; x += 12.4) for (const z of [bz0 + 3, bz1 - 3]) seg(B.p(CAP), [x, 0.3, z], [x, 12.5, z], 0.6, 6);
    flat(B.p(CAP), [[bx0, bz0], [bx1, bz0], [bx1, bz1], [bx0, bz1]], 12.5);
    const fold = 5, oF = B.p({c:'#dadcd9', m:0, lk:0.35, lc:'#fff1dc'}), oFG = B.p(GL);
    for (let i = 0; i < fold; i++){ const xa = lerp(bx0, bx1, i/fold), xb = lerp(bx0, bx1, (i + 1)/fold), xm = (xa + xb)/2, hm = i % 2 ? 31 : 36, he = 33.5;
      // roof ridges / valleys across the span (north-south), the folded end walls north and south
      q4(oF, [xa, he, bz0], [xm, hm, bz0 - 1.5], [xm, hm, bz1 + 1.5], [xa, he, bz1]); q4(oF, [xm, hm, bz0 - 1.5], [xb, he, bz0], [xb, he, bz1], [xm, hm, bz1 + 1.5]);
      for (const [z, zz] of [[bz0, bz0 - 1.5], [bz1, bz1 + 1.5]]){ t3(oF, [xa, 12.5, z], [xm, 12.5, zz], [xm, hm, zz]); t3(oF, [xa, 12.5, z], [xm, hm, zz], [xa, he, z]); t3(oF, [xm, 12.5, zz], [xb, 12.5, z], [xb, he, z]); t3(oF, [xm, 12.5, zz], [xb, he, z], [xm, hm, zz]); } }
    for (const x of [bx0, bx1]){ q4(oFG, [x, 12.5, bz0], [x, 12.5, bz1], [x, 33.5, bz1], [x, 33.5, bz0]); }
