    // the hotel block at the west end of the LOFT (white, punched windows, a roof terrace)
    prism(B.p(WALL), U.MU, -9, 28.3, false); prism(B.p(CAP), offP(U.MU, -0.25), 28.3, 28.9); flat(B.p(GREEN), offP(U.MU, 0.8), 28.95);
    for (const l of U.L){ const P = l[2], [lx0, lz0, lx1, lz1] = bbP(P), small = (lx1 - lx0)*(lz1 - lz0) < 120;
      const fl = small ? 1 : 2 + Math.floor(rng()*3), h = fl*4.2, W = rng() < 0.5 ? WALL : WALL2;
      prism(B.p(W), P, DY, DY + h - 0.6, false); prism(B.p(CAP), offP(P, -0.2), DY + h - 0.6, DY + h); flat(B.p(rng() < 0.6 ? GREEN : ROOF), offP(P, 0.6), DY + h + 0.05);
      if (!small && rng() < 0.5){ const [cx, cz] = cenP(P); treeP(B.p(TREE), B.p(TRUNK), cx, cz, DY + h, 0.7); } }
    // trees on the deck lanes
