// ================= Shenzhen Convention and Exhibition Center (gmp, opened 2004) =================
// 280 x 540 m; a 45 m wide, 540 m long concrete spine (30 x 30 m column grid, five service levels) with the exhibition halls on
// either side (spans 125 m, up to 38 m clear); on top of the spine at 45 m the convention centre cantilevers both ways into a
// platform 60 m wide and 360 m long; 65 m overall (sbp / gmp). Footprint OSM w146862823 (with its north forecourt facing the Civic
// Center) and its part w146862823 0-60 m (the platform). Roof trusses every 30 m (the spine's grid) span the halls.
LANDMARKS.szcec = {zh:'深圳会展中心', en:'Shenzhen Convention and Exhibition Center', cat:'new', r:328, h:65, lt:{m:0, c:'#ffe6c4', k:0.45, e:0.4},
  build(){
    const g = new THREE.Group(), B = mkB(), C = D.cec, R = C.R;
    const GLW = {c:'#7d93a0', m:0, lk:0.2, glow:'#ffe7c6', gk:0.5}, MUL = {c:'#d9dcdb', m:0, lk:0.35}, ROOF = '#b9bdbe', TRUSS = {c:'#eceeec', m:0, lk:0.5, lc:'#f1f5ff'},
      SPINE = {c:'#cfcac0', m:0, lk:0.4}, CONV = {c:'#86a0ac', m:0, lk:0.3, glow:'#ffe9c8', gk:0.65}, CAN = {c:'#e3e4e1', m:0, lk:0.45}, BASE = '#b6b0a5', PAVE = '#cfc9bd';
    const [sx0, sz0, sx1, sz1] = bbP(C.spine), scz = (sz0 + sz1)/2;     // the platform part: 360 x 56 m
    const zN = scz - 22.5, zS = scz + 22.5;                            // the spine (45 m)
    const [rx0, rz0, rx1, rz1] = bbP(R);
    // roof height over a hall: 26 m at the outer wall rising to 40 m at the spine (a shallow curve)
    const yr = z => { const d = z < scz ? (zN - z)/(zN - rz0) : (z - zS)/(rz1 - zS); return 40 - 14*Math.pow(cl01(d), 1.6); };
    // walls: glazed all round, from a granite base to the roof edge (the roof height at the wall's z)
    const oW = B.p(GLW), oM = B.p(MUL);
    for (let i = 0; i < R.length; i++){ const a = R[i], b = R[(i + 1) % R.length], ya = Math.min(yr(a[1]), 45), yb = Math.min(yr(b[1]), 45);
      q4(oW, [a[0], 1.2, a[1]], [b[0], 1.2, b[1]], [b[0], yb, b[1]], [a[0], ya, a[1]]);
      const [nx, nz, ux, uz, l] = edgeN(R, i), n = Math.max(1, Math.round(l/7.5));
      for (let k = 0; k <= n; k++){ const x = a[0] + ux*l*k/n, z = a[1] + uz*l*k/n, y = Math.min(yr(z), 45); q4(oM, [x, 1.2, z], [x + nx*0.7, 1.2, z + nz*0.7], [x + nx*0.7, y, z + nz*0.7], [x, y, z]); }
      for (const y of [8, 16]) q4(oM, [a[0] + nx*0.2, y, a[1] + nz*0.2], [b[0] + nx*0.2, y, b[1] + nz*0.2], [b[0] + nx*0.2, y + 0.8, b[1] + nz*0.2], [a[0] + nx*0.2, y + 0.8, a[1] + nz*0.2]);
      q4(B.p(BASE), [a[0] + nx*0.3, -2, a[1] + nz*0.3], [b[0] + nx*0.3, -2, b[1] + nz*0.3], [b[0] + nx*0.3, 1.2, b[1] + nz*0.3], [a[0] + nx*0.3, 1.2, a[1] + nz*0.3]); }
    // the hall roofs: strips across the plan, following yr(z), clipped to the footprint by triangulating per x-band
    const oRf = B.p(ROOF), xs = []; for (let x = rx0; x < rx1; x += 10) xs.push(x); xs.push(rx1);
    const zs = []; for (let z = rz0; z <= rz1 + 0.01; z += 6) zs.push(Math.min(z, rz1));
    const inside = (P, x, z) => { let c = false; for (let i = 0, j = P.length - 1; i < P.length; j = i++){ const a = P[i], b = P[j]; if ((a[1] > z) !== (b[1] > z) && x < (b[0] - a[0])*(z - a[1])/(b[1] - a[1]) + a[0]) c = !c; } return c; };
    for (let i = 0; i < xs.length - 1; i++) for (let j = 0; j < zs.length - 1; j++){ const x0 = xs[i], x1 = xs[i + 1], z0 = zs[j], z1 = zs[j + 1];
      if (!inside(R, (x0 + x1)/2, (z0 + z1)/2)) continue; if ((z0 + z1)/2 > zN && (z0 + z1)/2 < zS) continue;
      q4(oRf, [x0, yr(z0), z0], [x1, yr(z0), z0], [x1, yr(z1), z1], [x0, yr(z1), z1]); }
    // roof trusses every 30 m across each hall: an arched top chord over the roof, verticals, and their bearing on the walls
    const oT = B.p(TRUSS);
    for (let x = sx0 - 90; x <= sx1 + 90; x += 30){ if (x < rx0 + 8 || x > rx1 - 8) continue;
      for (const side of [-1, 1]){ const zOut = side < 0 ? rz0 + 2 : rz1 - 2, zIn = side < 0 ? zN : zS, n = 10; let pr = null;
        for (let k = 0; k <= n; k++){ const z = lerp(zOut, zIn, k/n), y = yr(z) + 2 + 3.2*Math.sin(PI*k/n), p = [x, y, z];
          if (!inside(R, x, z)) { pr = null; continue; }
          if (pr) seg(oT, pr, p, 0.55, 4); seg(oT, [x, yr(z), z], p, 0.25, 3); pr = p; } } }
    // the spine: concrete between the halls up to 45 m (its ends show on the east / west fronts)
    prism(B.p(SPINE), [[rx0 + 1, zN], [rx1 - 1, zN], [rx1 - 1, zS], [rx0 + 1, zS]], 0, 45);
    // the entrance halls at both ends of the spine (OSM w781193993 / w781193995): glazed, under a flat roof
    for (const P of C.ends){ prism(B.p(GLW), offP(P, 0.8), 0.3, 21, false); prism(B.p(CAN), offP(P, -0.6), 21, 23, true, true); finsP(oM, offP(P, 0.8), 0.3, 21, 6, 0.5, 0.2, 1); }
    // the convention platform 45-65 m: glazed, floor bands, a deep flat roof overhanging all round
    const PL = [[sx0, sz0], [sx1, sz0], [sx1, sz1], [sx0, sz1]];
    prism(B.p(SPINE), offP(PL, -0.3), 45, 47.5, true, true);
    prism(B.p(CONV), offP(PL, 1.2), 47.5, 62.5, false);
    finsP(oM, offP(PL, 1.2), 47.5, 62.5, 7.5, 0.6, 0.25, 1);
    prism(B.p(CAN), offP(PL, -3.5), 62.5, 65, true, true);
    // the north forecourt: the tall entrance wall (glazed, in the footprint), a canopy on slender columns over the entrance
    const notch = R.filter(p => p[1] > rz0 + 20 && p[1] < scz - 40 && Math.abs(p[0]) < 80);
    if (notch.length >= 2){ const nz = Math.max(...notch.map(p => p[1])), nx0 = Math.min(...notch.map(p => p[0])), nx1 = Math.max(...notch.map(p => p[0]));
      abox(B.p(CAN), nx0 + 4, nx1 - 4, 24, 25.8, nz - 16, nz);
      for (let x = nx0 + 8; x <= nx1 - 8; x += 13) seg(B.p(MUL), [x, 0.3, nz - 14.5], [x, 24, nz - 14.5], 0.45, 6);
      flat(B.p(PAVE), [[nx0 + 1, rz0 + 3], [nx1 - 1, rz0 + 3], [nx1 - 1, nz], [nx0 + 1, nz]], 0.25); }
    B.flush(g);
    return g;
  }};
SG_PLACES.push({type:'szcec', lat:D.cec.a[0], lon:D.cec.a[1], rot:D.cec.a[2]});

// ================= Gangxia North Hub: the "Shenzhen Eye" (opened 28 October 2022) =================
// The interchange of Metro Lines 2/8, 10, 11 and 14 under the Shennan Boulevard / Caitian Road junction (Wikipedia, bendibao).
// Its core atrium (51.2 x 48 m, a column-free steel structure under a white grid dome after the Fermat spiral) is lit by a 9 m
// round oculus; the hub has 26 rooflights and 23 entrances (ifeng, bendibao, Wikipedia). At street level: the oculus, a glass
// disc with Fermat-spiral ribs in a round paved plaza, smaller round rooflights and an entrance pavilion. Placement: the station's
// footprint (r15525717) south of Shennan Boulevard, east of Caitian Road, on the green strip by exit 12 (the exact position of the
// oculus is not mapped: see the report).
LANDMARKS.szgangxia = {zh:'岗厦北综合交通枢纽', en:'Gangxia North Hub', cat:'new', r:50, h:6.5, lt:{m:0, c:'#fff0d8', k:0.5},
  build(){
    const g = new THREE.Group(), B = mkB();
    const GLS = {c:'#86a3b3', m:0, lk:0.5, glow:'#f4f0e4', gk:0.9, op:0.8}, RIB = {c:'#eef0ee', m:0, lk:0.6, glow:'#ffffff', gk:0.25}, PAVE = '#cdc7bb', CURB = {c:'#d9d6cf', m:0, lk:0.4},
      LAWN = '#7d9a5e', CAN = {c:'#e4e5e2', m:0, lk:0.45}, ENT = {c:'#4a5860', glow:'#ffe7c4', gk:0.6}, TREE = '#5a7a4b';
    const circ = (r, n, cx, cz) => { const P = []; for (let k = 0; k < n; k++){ const a = k/n*TAU; P.push([(cx || 0) + Math.cos(a)*r, (cz || 0) + Math.sin(a)*r]); } return P; };
    // the paved plaza, the curb ring, the glass oculus (shallow dome 9 m across), its Fermat-spiral ribs
    prism(B.p(PAVE), circ(16, 40), -0.6, 0.25); prism(B.p(LAWN), circ(19.5, 40), -0.6, 0.1);
    prism(B.p(CURB), circ(5.3, 40), 0.25, 1.0); flat(B.p(CURB), circ(5.3, 40), 1.0);
    const dome = [0, 0.3, 0.6, 0.85, 1].map(f => { const r = 4.5*Math.cos(f*PI/2*0.9), y = 1.0 + 1.3*Math.sin(f*PI/2); return circ(Math.max(0.15, r), 32).map(p => [p[0], y, p[1]]); });
    loft(B.p(GLS), dome, true);
    const oR = B.p(RIB);
    for (const dir of [1, -1]) for (let k = 0; k < 13; k++){ let pr = null; for (let s = 0; s <= 8; s++){ const f = s/8, r = 4.5*Math.sqrt(1 - f*0.98), a = k/13*TAU + dir*f*2.2, y = 1.0 + 1.3*Math.sqrt(Math.max(0, 1 - (r/4.5)*(r/4.5))) + 0.05;
      const p = [Math.cos(a)*r, y, Math.sin(a)*r]; if (pr) seg(oR, pr, p, 0.07, 3); pr = p; } }
    // smaller round rooflights along the strip, flush with low curbs
    for (const [x, z, r] of [[-26, 0, 2.2], [26, 1, 2.2], [-34, 8, 1.6], [34, -6, 1.6]]){ prism(B.p(CURB), circ(r + 0.4, 20, x, z), 0, 0.6); prism(B.p(GLS), circ(r, 20, x, z), 0.6, 0.75); }
    // the entrance pavilion at exit 12 (a glass box under a thin white canopy)
    prism(B.p(ENT), [[29, -6], [41, -6], [41, 2], [29, 2]], 0, 3.6, false); abox(B.p(CAN), 27.5, 42.5, 3.6, 4.1, -7.5, 3.5);
    for (let k = 0; k < 8; k++){ const a = k/8*TAU + 0.3; treeP(B.p(TREE), B.p(TRUNK), Math.cos(a)*18, Math.sin(a)*18, 0.1, 1.2); }
    B.flush(g);
    return g;
  }};
SG_PLACES.push({type:'szgangxia', lat:D.gx.a[0], lon:D.gx.a[1], rot:D.gx.a[2]});

